/** Public entry point — the only module consumers/docs should import from. */

export {
  useDataGridPagination,
  type UseDataGridPaginationClientOptions,
  type UseDataGridPaginationServerOptions,
  type UseDataGridPaginationResult,
  type DataGridPaginationControls,
} from "./use-data-grid-pagination";
export {
  DataGridPaginationBar,
  type DataGridPaginationBarProps,
  DataGridPaginationRange,
  DataGridPaginationPageSize,
  DataGridPaginationFirst,
  DataGridPaginationPrev,
  DataGridPaginationPages,
  type DataGridPaginationPagesProps,
  DataGridPaginationNext,
  DataGridPaginationLast,
} from "./pagination-footer";
export { pageCount, clampPage, pageRange, pageWindow } from "./pagination-math";

"use client";

import { useMemo, useState } from "react";
import { clampPage, pageCount, pageRange } from "./pagination-math";

/** Default page-size choices offered by `<DataGridPaginationBar />`'s select, and the initial `pageSize` when none is given. */
const DEFAULT_PAGE_SIZES = [10, 25, 50, 100] as const;

/** Controls shared by client and server mode — what `<DataGridPaginationBar {...pager.controls} />` spreads. */
export type DataGridPaginationControls = {
  page: number;
  pageCount: number;
  pageSize: number;
  pageSizeOptions: readonly number[];
  total: number;
  onPageChange: (page: number) => void;
  onPageSizeChange: (pageSize: number) => void;
};

/** Client-mode options: `useDataGridPagination` slices `data` itself. */
export type UseDataGridPaginationClientOptions<TData> = {
  data: readonly TData[];
  pageSize?: number;
  pageSizeOptions?: readonly number[];
  /** Uncontrolled by default (internal `useState`); pass both to control the current page yourself. */
  page?: number;
  onPageChange?: (page: number) => void;
};

/** Server-mode options: consumer owns `page`/`pageSize`/`total` and fetches `pageData` itself — this hook is just the windowing math + controls shape. */
export type UseDataGridPaginationServerOptions = {
  page: number;
  pageSize: number;
  total: number;
  onPageChange: (page: number) => void;
  pageSizeOptions?: readonly number[];
  onPageSizeChange?: (pageSize: number) => void;
};

export type UseDataGridPaginationResult<TData> = {
  /** The current page's slice — client mode only; server mode returns `undefined` (you already have your own fetched page). */
  pageData: readonly TData[] | undefined;
  controls: DataGridPaginationControls;
};

function isServerOptions<TData>(
  options: UseDataGridPaginationClientOptions<TData> | UseDataGridPaginationServerOptions,
): options is UseDataGridPaginationServerOptions {
  return "total" in options;
}

/**
 * Pagination math + controls for `DataGrid` (pagination design doc, add-on 2): purely additive,
 * zero core changes — pagination slices/labels a dataset the grid already renders in full via
 * virtualization, it doesn't change how the grid renders.
 *
 * Client mode (`{ data, pageSize }`): slices `data` into `pageData` internally, page state is
 * uncontrolled unless you pass `page`/`onPageChange` yourself.
 *
 * Server mode (`{ page, pageSize, total, onPageChange }`): fully controlled — you own the page
 * index and fetch each page's rows yourself; this hook only computes `pageCount`/windowing and
 * hands back the same `controls` shape so `<DataGridPaginationBar />` doesn't need to know which mode
 * it's rendering for.
 */
const EMPTY_CLIENT_DATA: readonly never[] = [];

export function useDataGridPagination<TData>(
  options: UseDataGridPaginationClientOptions<TData> | UseDataGridPaginationServerOptions,
): UseDataGridPaginationResult<TData> {
  const server = isServerOptions(options);
  // Client hooks must run unconditionally (rules-of-hooks) — server mode feeds them inert inputs.
  const clientResult = useClientPagination<TData>(server ? { data: EMPTY_CLIENT_DATA } : options);
  if (server) {
    const { page, pageSize, total, onPageChange, pageSizeOptions = DEFAULT_PAGE_SIZES, onPageSizeChange } = options;
    const clampedPage = clampPage(page, total, pageSize);
    const controls: DataGridPaginationControls = {
      page: clampedPage,
      pageCount: pageCount(total, pageSize),
      pageSize,
      pageSizeOptions,
      total,
      onPageChange,
      onPageSizeChange: onPageSizeChange ?? (() => {}),
    };
    return { pageData: undefined, controls };
  }

  return clientResult;
}

function useClientPagination<TData>(options: UseDataGridPaginationClientOptions<TData>): UseDataGridPaginationResult<TData> {
  const { data, pageSizeOptions = DEFAULT_PAGE_SIZES, onPageChange: onPageChangeProp } = options;
  const [pageSize, setPageSize] = useState(options.pageSize ?? pageSizeOptions[0] ?? DEFAULT_PAGE_SIZES[0]);
  const [internalPage, setInternalPage] = useState(1);

  const controlledPage = options.page;
  const controlled = controlledPage !== undefined;
  const rawPage = controlled ? controlledPage : internalPage;
  const page = clampPage(rawPage, data.length, pageSize);

  const setPage = (next: number, sizeForClamp: number = pageSize) => {
    const clamped = clampPage(next, data.length, sizeForClamp);
    if (!controlled) setInternalPage(clamped);
    onPageChangeProp?.(clamped);
  };

  const pageData = useMemo(() => {
    const { start, end } = pageRange(page, pageSize, data.length);
    return data.slice(start, end);
  }, [data, page, pageSize]);

  const controls: DataGridPaginationControls = {
    page,
    pageCount: pageCount(data.length, pageSize),
    pageSize,
    pageSizeOptions,
    total: data.length,
    onPageChange: setPage,
    onPageSizeChange: (nextSize) => {
      setPageSize(nextSize);
      // keep the same first-visible row across a page-size change, per spec's "clamping on page-size change" test.
      const firstRow = (page - 1) * pageSize;
      setPage(Math.floor(firstRow / nextSize) + 1, nextSize);
    },
  };

  return { pageData, controls };
}

"use client";

import { createContext, use, type ReactNode } from "react";
import { ChevronLeft, ChevronRight, ChevronsLeft, ChevronsRight } from "lucide-react";
import { cn } from "@/lib/utils";
import { Button } from "@/components/ui/button";
import { Select, SelectContent, SelectItem, SelectTrigger, SelectValue } from "@/components/ui/select";
import { DEFAULT_LABELS, type DataGridPaginationLabels } from "@/registry/default/components/data-grid/data-grid";
import type { DataGridPaginationControls } from "./use-data-grid-pagination";
import { pageWindow } from "./pagination-math";

/** Default window size for {@link DataGridPaginationPages} when its `windowSize` prop is omitted. */
const DEFAULT_PAGE_WINDOW_SIZE = 5;

type PaginationBarContextValue = {
  controls: DataGridPaginationControls;
  labels: DataGridPaginationLabels;
};

const PaginationBarContext = createContext<PaginationBarContextValue | null>(null);

/** Resolves the enclosing bar's context, throwing with a clear message outside {@link DataGridPaginationBar}. */
function usePaginationBarContext(part: string): PaginationBarContextValue {
  const ctx = use(PaginationBarContext);
  if (!ctx) {
    throw new Error(`gridcn: <${part} /> must be used inside a <DataGridPaginationBar>.`);
  }
  return ctx;
}

/** Props for {@link DataGridPaginationBar}. */
export type DataGridPaginationBarProps = DataGridPaginationControls & {
  className?: string;
  /**
   * i18n override for this footer's strings, deep-merge semantics like core's `labels` prop
   * (see `deepMergeLabels`). Standalone default since this component renders outside
   * `DataGridProvider` in the spec's usage (`<DataGrid /><DataGridPaginationBar /></>` as siblings)
   * and so has no store to read `useDataGridLabels()` from.
   */
  labels?: Partial<DataGridPaginationLabels>;
  /** Custom composition of parts; omit to render the default layout (range, page-size, first/prev/pages/next/last). */
  children?: ReactNode;
};

/**
 * Pagination footer bar: provides the shared `DataGridPaginationControls` + merged labels to its
 * children via context, shadcn-`Pagination` style. With no `children` it renders the default
 * layout so the common case stays a one-liner; pass `children` built from the parts below
 * (`DataGridPaginationRange`, `DataGridPaginationPageSize`, `DataGridPaginationFirst`,
 * `DataGridPaginationPrev`, `DataGridPaginationPages`, `DataGridPaginationNext`,
 * `DataGridPaginationLast`) for a custom arrangement.
 *
 * Works identically for client and server mode — both produce the same
 * `DataGridPaginationControls` shape from `useDataGridPagination`, so this component never knows
 * which mode it's rendering for.
 */
export function DataGridPaginationBar(props: DataGridPaginationBarProps): ReactNode {
  const { page, pageCount, pageSize, pageSizeOptions, total, onPageChange, onPageSizeChange, className, labels: labelsOverride, children } = props;
  const controls: DataGridPaginationControls = { page, pageCount, pageSize, pageSizeOptions, total, onPageChange, onPageSizeChange };
  const labels = { ...DEFAULT_LABELS.pagination, ...labelsOverride };

  return (
    <PaginationBarContext value={{ controls, labels }}>
      <div data-grid-pagination="" className={cn("flex flex-wrap items-center justify-between gap-2 border-t border-border bg-background px-2 py-1.5", className)}>
        {children ?? (
          <>
            <DataGridPaginationRange />
            <div className="flex flex-wrap items-center gap-3">
              <DataGridPaginationPageSize />
              <div className="flex items-center gap-1">
                <DataGridPaginationFirst />
                <DataGridPaginationPrev />
                <DataGridPaginationPages />
                <DataGridPaginationNext />
                <DataGridPaginationLast />
              </div>
            </div>
          </>
        )}
      </div>
    </PaginationBarContext>
  );
}

/** The "x–y of z" range label (or {@link DataGridPaginationLabels.rangeEmpty} when `total` is 0). */
export function DataGridPaginationRange(): ReactNode {
  const { controls, labels } = usePaginationBarContext("DataGridPaginationRange");
  const { page, pageSize, total } = controls;
  const from = total === 0 ? 0 : (page - 1) * pageSize + 1;
  const to = Math.min(page * pageSize, total);

  return <span className="text-xs tabular-nums text-muted-foreground">{total === 0 ? labels.rangeEmpty : labels.range(from, to, total)}</span>;
}

/** The rows-per-page `Select`. */
export function DataGridPaginationPageSize(): ReactNode {
  const { controls, labels } = usePaginationBarContext("DataGridPaginationPageSize");
  const { pageSize, pageSizeOptions, onPageSizeChange } = controls;

  return (
    <Select value={String(pageSize)} onValueChange={(value) => onPageSizeChange(Number(value))}>
      <SelectTrigger className="h-8 w-fit" aria-label={labels.pageSizeAriaLabel}>
        <SelectValue />
      </SelectTrigger>
      <SelectContent>
        {pageSizeOptions.map((size) => (
          <SelectItem key={size} value={String(size)}>
            {labels.pageSizeOption(size)}
          </SelectItem>
        ))}
      </SelectContent>
    </Select>
  );
}

/** Jump to page 1; disabled on page 1. */
export function DataGridPaginationFirst(): ReactNode {
  const { controls, labels } = usePaginationBarContext("DataGridPaginationFirst");
  const { page, onPageChange } = controls;

  return (
    <Button type="button" variant="ghost" size="icon-sm" aria-label={labels.firstPage} disabled={page <= 1} onClick={() => onPageChange(1)}>
      <ChevronsLeft />
    </Button>
  );
}

/** Page − 1; disabled on page 1. */
export function DataGridPaginationPrev(): ReactNode {
  const { controls, labels } = usePaginationBarContext("DataGridPaginationPrev");
  const { page, onPageChange } = controls;

  return (
    <Button type="button" variant="ghost" size="icon-sm" aria-label={labels.previousPage} disabled={page <= 1} onClick={() => onPageChange(page - 1)}>
      <ChevronLeft />
    </Button>
  );
}

/** Props for {@link DataGridPaginationPages}. */
export type DataGridPaginationPagesProps = {
  /** How many numbered page buttons to show at once (see {@link pageWindow}). */
  windowSize?: number;
};

/** The windowed numbered page buttons — the only source of page numbers in the composable layout. */
export function DataGridPaginationPages(props: DataGridPaginationPagesProps): ReactNode {
  const { windowSize = DEFAULT_PAGE_WINDOW_SIZE } = props;
  const { controls, labels } = usePaginationBarContext("DataGridPaginationPages");
  const { page, pageCount, onPageChange } = controls;
  const pages = pageWindow(page, pageCount, windowSize);

  return (
    <>
      {pages.map((p) => (
        <Button
          key={p}
          type="button"
          variant={p === page ? "default" : "ghost"}
          size="icon-sm"
          aria-label={labels.pageAriaLabel(p)}
          aria-current={p === page ? "page" : undefined}
          onClick={() => onPageChange(p)}
        >
          {p}
        </Button>
      ))}
    </>
  );
}

/** Page + 1; disabled on the last page. */
export function DataGridPaginationNext(): ReactNode {
  const { controls, labels } = usePaginationBarContext("DataGridPaginationNext");
  const { page, pageCount, onPageChange } = controls;

  return (
    <Button type="button" variant="ghost" size="icon-sm" aria-label={labels.nextPage} disabled={page >= pageCount} onClick={() => onPageChange(page + 1)}>
      <ChevronRight />
    </Button>
  );
}

/** Jump to the last page; disabled on the last page. */
export function DataGridPaginationLast(): ReactNode {
  const { controls, labels } = usePaginationBarContext("DataGridPaginationLast");
  const { page, pageCount, onPageChange } = controls;

  return (
    <Button type="button" variant="ghost" size="icon-sm" aria-label={labels.lastPage} disabled={page >= pageCount} onClick={() => onPageChange(pageCount)}>
      <ChevronsRight />
    </Button>
  );
}

/** Total pages for `total` rows at `pageSize` per page — at least 1 even when `total` is 0 (an empty grid still shows "page 1"). */
export function pageCount(total: number, pageSize: number): number {
  if (pageSize <= 0) return 1;
  return Math.max(1, Math.ceil(total / pageSize));
}

/** Clamps `page` (1-based) into `[1, pageCount(total, pageSize)]` — the fallback when data shrinks or pageSize changes out from under the current page. */
export function clampPage(page: number, total: number, pageSize: number): number {
  return Math.min(Math.max(1, Math.floor(page)), pageCount(total, pageSize));
}

/** Half-open `[start, end)` row range for `page` (1-based) at `pageSize`, clamped to `total`. */
export function pageRange(page: number, pageSize: number, total: number): { start: number; end: number } {
  const start = Math.min((page - 1) * pageSize, total);
  const end = Math.min(start + pageSize, total);
  return { start, end };
}

/**
 * Windowed page numbers for the footer, e.g. page 7 of 20 with windowSize 5 -> [5,6,7,8,9].
 * The window slides to stay centered on `page` but clamps at both ends so it never runs past
 * `[1, pageCount]` or shows fewer than `windowSize` numbers when there's room for that many.
 */
export function pageWindow(page: number, pageCount: number, windowSize: number): number[] {
  if (pageCount <= 0) return [];
  const size = Math.max(1, Math.min(windowSize, pageCount));
  let start = page - Math.floor(size / 2);
  start = Math.max(1, Math.min(start, pageCount - size + 1));
  return Array.from({ length: size }, (_, i) => start + i);
}
